using System.Runtime.CompilerServices;using System.Text.Json;using DeskCanvas.Core;
internal static class V30ContractTests{[ModuleInitializer]internal static void Run(){var c=new ClockOptions{Backgroundless=true,FontFamily="no-such-font",TextColor="not-a-color",FontWeight=ClockFontWeight.Black,SurfaceStyle=WidgetSurfaceStyle.MinimalGlass};var copy=c.Clone();if(!copy.Backgroundless||copy.FontWeight!=ClockFontWeight.Black||copy.SurfaceStyle!=WidgetSurfaceStyle.MinimalGlass)throw new Exception();var parsed=JsonSerializer.Deserialize<ClockOptions>(JsonSerializer.Serialize(c))!;if(!parsed.Backgroundless||parsed.FontWeight!=ClockFontWeight.Black||parsed.SurfaceStyle!=WidgetSurfaceStyle.MinimalGlass)throw new Exception();var playing=new NowPlayingOptions{SurfaceStyle=WidgetSurfaceStyle.MinimalGlass};if(playing.Clone().SurfaceStyle!=WidgetSurfaceStyle.MinimalGlass)throw new Exception();var items=new[]{new CanvasItem{ZIndex=int.MaxValue},new CanvasItem{ZIndex=-99}}.OrderBy(x=>x.ZIndex).ToArray();for(var i=0;i<items.Length;i++)items[i].ZIndex=i;if(items[0].ZIndex!=0||items[1].ZIndex!=1)throw new Exception();Console.WriteLine("PASS v3.0 clock options and layer normalization");}}
